const button=document.querySelector('.menu-toggle');const nav=document.querySelector('.mobile-nav');button?.addEventListener('click',()=>{const open=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!open));button.setAttribute('aria-label',open?'Open menu':'Close menu');nav.hidden=open});nav?.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{nav.hidden=true;button.setAttribute('aria-expanded','false');button.setAttribute('aria-label','Open menu')}));
